#!/usr/bin/env bash

# Renders Minimum Feedback Arc Set GraphViz DOT files as SVG visualizations.
# Reads .gv files generated by "cyclicDependenciesMinimumFeedbackArcSetPython.sh"
# (via minimumFeedbackArcSetCharts.py) and renders them to SVG.
# Produces one SVG per Strongly Connected Component for Java Packages and SCIP Semantic Index Modules.
# The SVG files will be written into reports/cyclic-dependencies/{Java_Package,SCIP_Semantic_Index_Module}/Graph_Visualizations/.
# Dynamically triggered by "VisualizationReports.sh".

# Requires renderGraphVizSVG.sh
# Requires cyclicDependenciesMinimumFeedbackArcSetPython.sh to have run first (provides the .gv input files)

# Fail on any error ("-e" = exit on first error, "-o pipefail" exist on errors within piped commands)
set -o errexit -o pipefail -o nounset
IFS=$'\n\t'

usage() {
    echo "Usage: source ${BASH_SOURCE[0]} [--help]"
    echo ""
    echo "Renders Minimum Feedback Arc Set GraphViz DOT files to SVG for each Strongly Connected Component."
    echo ""
    echo "Environment variables:"
    echo "  REPORTS_DIRECTORY   Report output base directory (default: reports)"
}

if [ "${1:-}" = "--help" ]; then
    usage
    exit 0
fi

# Overrideable constants
REPORTS_DIRECTORY=${REPORTS_DIRECTORY:-"reports"}

## Get this "domains/cyclic-dependencies" directory if not already set
# Even if $BASH_SOURCE is made for Bourne-like shells it is also supported by others and therefore here the preferred solution.
# CDPATH reduces the scope of the cd command to potentially prevent unintended directory changes.
# This way non-standard tools like readlink aren't needed.
CYCLIC_DEPENDENCIES_SCRIPT_DIR=${CYCLIC_DEPENDENCIES_SCRIPT_DIR:-$( (unset CDPATH; cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P) )}
echo "cyclicDependenciesMinimumFeedbackArcSetVisualization: CYCLIC_DEPENDENCIES_SCRIPT_DIR=${CYCLIC_DEPENDENCIES_SCRIPT_DIR}"

# Get the "scripts" directory by navigating two levels up from this domain directory
SCRIPTS_DIR=${SCRIPTS_DIR:-"${CYCLIC_DEPENDENCIES_SCRIPT_DIR}/../../scripts"}

# Get the "scripts/visualization" directory
VISUALIZATION_SCRIPTS_DIR=${VISUALIZATION_SCRIPTS_DIR:-"${SCRIPTS_DIR}/visualization"}

REPORT_NAME="cyclic-dependencies"
FULL_REPORT_DIRECTORY="${REPORTS_DIRECTORY}/${REPORT_NAME}"
GRAPH_VISUALIZATIONS_DIRECTORY_NAME="Graph_Visualizations"
GRAPHVIZ_SUBDIRECTORY_NAME="graphviz"

# Render all Minimum Feedback Arc Set .gv files in a given visualizations directory.
# Each .gv file is rendered to SVG, then moved into a "graphviz" subdirectory.
#
# Parameters:
#   $1  visualizations_directory  — directory containing .gv files
#   $2  language_label            — human-readable label for log messages
render_minimum_feedback_arc_set_graphs() {
    local visualizations_directory="${1}"
    local language_label="${2}"

    if [ ! -d "${visualizations_directory}" ]; then
        echo "cyclicDependenciesMinimumFeedbackArcSetVisualization: No ${language_label} visualization directory found in ${visualizations_directory}. Skipping."
        return 0
    fi

    # Count .gv files to process
    local gv_file_count
    gv_file_count=$(find "${visualizations_directory}" -maxdepth 1 -name "Minimum_Feedback_Arc_Set_*.gv" | wc -l | tr -d ' ')

    if [ "${gv_file_count}" -eq 0 ]; then
        echo "cyclicDependenciesMinimumFeedbackArcSetVisualization: No Minimum Feedback Arc Set .gv files found in ${visualizations_directory}. Skipping (run Python report first)."
        return 0
    fi

    echo "cyclicDependenciesMinimumFeedbackArcSetVisualization: $(date +'%Y-%m-%dT%H:%M:%S%z') Rendering ${gv_file_count} ${language_label} Minimum Feedback Arc Set graph(s)..."

    local graphviz_subdirectory="${visualizations_directory}/${GRAPHVIZ_SUBDIRECTORY_NAME}"
    mkdir -p "${graphviz_subdirectory}"

    while IFS= read -r gv_file; do
        # SC1091: sourced file is a pipeline-provided utility resolved at runtime via a variable path
        # shellcheck disable=SC1091
        ( source "${VISUALIZATION_SCRIPTS_DIR}/renderGraphVizSVG.sh" "${gv_file}" ) || true
        mv -f "${gv_file}" "${graphviz_subdirectory}/" || true
    done < <(find "${visualizations_directory}" -maxdepth 1 -name "Minimum_Feedback_Arc_Set_*.gv" | sort)

    echo "cyclicDependenciesMinimumFeedbackArcSetVisualization: $(date +'%Y-%m-%dT%H:%M:%S%z') ${language_label} rendering completed."
}

# ── Java Package Minimum Feedback Arc Set ─────────────────────────────────────

render_minimum_feedback_arc_set_graphs \
    "${FULL_REPORT_DIRECTORY}/Java_Package/${GRAPH_VISUALIZATIONS_DIRECTORY_NAME}" \
    "Java Package"

# ── SCIP Semantic Index Module Minimum Feedback Arc Set ───────────────────────

render_minimum_feedback_arc_set_graphs \
    "${FULL_REPORT_DIRECTORY}/SCIP_Semantic_Index_Module/${GRAPH_VISUALIZATIONS_DIRECTORY_NAME}" \
    "SCIP Semantic Index Module"

echo "cyclicDependenciesMinimumFeedbackArcSetVisualization: $(date +'%Y-%m-%dT%H:%M:%S%z') Successfully finished."
